import java.util.ArrayList;
import java.util.List;

// 준비 값: 프레임 수와 요청 목록이에요.
// R=읽기, W=쓰기(페이지가 더티가 돼요), P=고정(사용 중이라 내보내면 안 돼요), U=고정 풀기.
static final int FRAMES = 3;
static final String REQUESTS = "W1 P1 R2 R3 R4 U1 R5";

// 준비 코드: 프레임 한 칸이에요. pin은 지금 쓰는 사람 수, dirty는 디스크에 아직 안 쓴 변경이에요.
static class Frame {
    int page; int pin; boolean dirty; int lastUsed;
    Frame(int page) { this.page = page; }
}
static final List<Frame> pool = new ArrayList<>();
static int clock = 0, diskReads = 0, diskWrites = 0;

// 내보낼 프레임을 골라요. 고정되지 않은 프레임 가운데 가장 오래전에 쓴 것(LRU)이어야 해요.
static Frame chooseVictim() {
    Frame victim = null;
    for (Frame f : pool) {
        // 고칠 곳: 지금은 고정 여부를 보지 않고 가장 오래전에 쓴 프레임을 골라요.
        if (victim == null || f.lastUsed < victim.lastUsed) victim = f;
    }
    return victim;
}

// 준비 코드: 페이지를 버퍼 풀로 가져와요. 있으면 적중, 없으면 디스크에서 읽어요.
static Frame fetch(int page, String request) {
    clock++;
    for (Frame f : pool) {
        if (f.page == page) {
            f.lastUsed = clock;
            System.out.println("요청 " + request + " | 적중 | 풀 " + show());
            return f;
        }
    }
    String note = "미스";
    if (pool.size() == FRAMES) {
        Frame victim = chooseVictim();
        if (victim == null) {
            System.out.println("요청 " + request + " | 실패 모든 프레임이 고정됨 | 풀 " + show());
            return null;
        }
        if (victim.pin > 0) note += " 오류 고정된 " + victim.page + "번을 내보냄";
        if (victim.dirty) { diskWrites++; note += " 쓰기 " + victim.page + "번"; }
        note += " 퇴출 " + victim.page + "번";
        pool.remove(victim);
    }
    Frame frame = new Frame(page);
    frame.lastUsed = clock;
    diskReads++;
    pool.add(frame);
    System.out.println("요청 " + request + " | " + note + " | 풀 " + show());
    return frame;
}

static String show() {
    StringBuilder out = new StringBuilder();
    for (Frame f : pool) {
        out.append("[").append(f.page).append(f.pin > 0 ? " 고정" : "").append(f.dirty ? " 더티" : "").append("]");
    }
    return out.toString();
}

void main() {
    for (String request : REQUESTS.trim().split("\\s+")) {
        char kind = request.charAt(0);
        int page = Integer.parseInt(request.substring(1));
        if (kind == 'U') {
            for (Frame f : pool) if (f.page == page && f.pin > 0) f.pin--;
            System.out.println("요청 " + request + " | 고정 풀기 | 풀 " + show());
            continue;
        }
        Frame f = fetch(page, request);
        if (f == null) continue;
        if (kind == 'W') f.dirty = true;
        if (kind == 'P') f.pin++;
    }
    System.out.println("디스크 읽기 " + diskReads + "번, 디스크 쓰기 " + diskWrites + "번");
}

